module protocol::adl_admin;

use std::option::{none, some};
use std::type_name::TypeName;

use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::adl::DeleverageParams;
use math::float;
use protocol::adl::new_auto_deleverage_params;

const BPS_DENOMINATOR: u64 = 10000;
const LARGE_DENOMINATOR: u64 = 1000000000000000000;
const MAX_DELAY_SECONDS: u64 = 259200; // 3 days

public struct NewADLSetEvent has copy, drop {
    market: TypeName,
    coin: TypeName,

    is_borrow: bool,
    emode_group_id: Option<u8>,

    params: DeleverageParams,
    activation_timestamp: u64,

    time: u64,
    operator: address,
}

public struct ADLCancelEvent has copy, drop {
    market: TypeName,
    coin: TypeName,

    is_borrow: bool,
    emode_group_id: Option<u8>,

    time: u64,
    operator: address,
}

public fun new_adl_params<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &Market<MarketType>,

    target_amount: u64,

    liquidation_factor_base_bps: u64,
    liquidation_factor_hourly_drop_large: u64,

    liquidation_incentive_base_bps: u64,
    liquidation_incentive_daily_penalty_large: u64,

    close_factor_bps: u64,
): DeleverageParams {
    assert!(0 < liquidation_factor_base_bps && liquidation_factor_base_bps <= BPS_DENOMINATOR, error::invalid_params_error());
    assert!(0 < close_factor_bps && close_factor_bps <= BPS_DENOMINATOR, error::invalid_params_error());

    check_market<MarketType>(self, market);

    let liquidation_factor_base = float::from_quotient(liquidation_factor_base_bps, BPS_DENOMINATOR);
    let liquidation_factor_hourly_drop = float::from_quotient(liquidation_factor_hourly_drop_large, LARGE_DENOMINATOR);

    let liquidation_incentive_base = float::from_quotient(liquidation_incentive_base_bps, BPS_DENOMINATOR);
    let liquidation_incentive_daily_penalty = float::from_quotient(liquidation_incentive_daily_penalty_large, LARGE_DENOMINATOR);

    let close_factor = float::from_quotient(close_factor_bps, BPS_DENOMINATOR);

    new_auto_deleverage_params(
        target_amount, 
        liquidation_factor_base, 
        liquidation_factor_hourly_drop, 
        liquidation_incentive_base, 
        liquidation_incentive_daily_penalty, 
        close_factor
    )
}

public fun enable_collateral_adl<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,

    params: DeleverageParams,
    seconds_from_now: u64,

    clock: &Clock,
    ctx: &TxContext,
) {
    assert!(seconds_from_now <= MAX_DELAY_SECONDS, error::invalid_params_error());

    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();

    let now = clock.timestamp_ms() / 1000;
    let activation_timestamp = now + seconds_from_now;

    registry.enable_collateral_deleverage<CoinType>(params, activation_timestamp);

    emit(NewADLSetEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        coin: std::type_name::with_defining_ids<CoinType>(),

        is_borrow: false,
        emode_group_id: none(),

        params: params,
        activation_timestamp,

        time: now,
        operator: ctx.sender(),
    });
}

public fun cancel_collateral_adl<MarketType, CoinType>(
    _: &AdminCap,

    self: &ProtocolApp,
    market: &mut Market<MarketType>,

    clock: &Clock,
    ctx: &TxContext,
) {
    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();
    let market_type = std::type_name::with_defining_ids<MarketType>();

    registry.stop_collateral_deleverage<CoinType>(market_type);

    emit(ADLCancelEvent {
        market: market_type,
        coin: std::type_name::with_defining_ids<CoinType>(),
        is_borrow: false,
        emode_group_id: none(),
        time: clock.timestamp_ms(),
        operator: ctx.sender(),
    });
}

public fun enable_debt_adl<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,

    emode_group_id: u8,
    params: DeleverageParams,
    seconds_from_now: u64,

    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(seconds_from_now <= MAX_DELAY_SECONDS, error::invalid_params_error());

    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();

    let now = clock.timestamp_ms() / 1000;
    let activation_timestamp = now + seconds_from_now;

    registry.enable_debt_deleverage<CoinType>(emode_group_id, params, activation_timestamp, ctx);

    emit(NewADLSetEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        coin: std::type_name::with_defining_ids<CoinType>(),

        is_borrow: true,
        emode_group_id: some(emode_group_id),

        params: params,
        activation_timestamp,

        time: now,
        operator: ctx.sender(),
    });
}

public fun cancel_debt_adl<MarketType, CoinType>(
    _: &AdminCap,

    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    emode_group_id: u8,

    clock: &Clock,
    ctx: &mut TxContext,
) {
    check_market<MarketType>(self, market);

    let registry = market.adl_registry_mut();
    let market_type = std::type_name::with_defining_ids<MarketType>();

    registry.stop_borrow_deleverage<CoinType>(market_type, emode_group_id);

    emit(ADLCancelEvent {
        market: market_type,
        coin: std::type_name::with_defining_ids<CoinType>(),

        is_borrow: true,
        emode_group_id: some(emode_group_id),

        time: clock.timestamp_ms() / 1000,
        operator: ctx.sender(),
    });
}

fun check_market<MarketType>(
    self: &ProtocolApp,
    market: &Market<MarketType>,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();
}

    let collateral_params = timelock.inner();
    collateral_params.ensure_limit_breached(total_deposit);
    let activation_time = timelock.get_secs_since_activation(clock);

    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::some(collateral_params.liquidation_ltv(activation_time)),
        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
        liquidation_incentive: collateral_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
        liquidation_revenue_factor: float::zero(),
        close_factor: collateral_params.close_factor(),
        close_factor_bypass_min_value,
    };

    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

fun try_stop_collateral_deleverage<MarketType, CollateralType>(id: &mut UID, reserves: &GenericCoinTypeStorage<Reserve<MarketType>>, collateral: TypeName) {
    let total_deposit = reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().ceil();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(id, ADLRegistryKey {});
    adl.try_stop_collateral_deleverage<CollateralType>(type_name::with_defining_ids<MarketType>(), total_deposit);
}

fun try_stop_borrow_deleverage<MarketType, DebtType>(market_id: &mut UID, emode_group_id: u8, emode_group: &EModeGroup, debt_type: TypeName) {
    let total_borrow = emode_group.borrow_amount(debt_type).floor();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(market_id, ADLRegistryKey {});
    adl.try_stop_borrow_deleverage<DebtType>(type_name::with_defining_ids<MarketType>(), emode_group_id, total_borrow);
}

fun liquidation_inner<MarketType, DebtType, CollateralType>(
    id: &mut UID,

    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    emode_group: &mut EModeGroup,

    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,

    obligation: &mut Obligation<MarketType>,
    liquidation_params: &LiquidationParams,

    mut available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    now: u64,

